class Solution:
    def canAttendMeetings(self, intervals: list[list[int]]) -> bool:
        intervals.sort(key=lambda i: i[0])
        curEnd = 0
        for i in range(len(intervals)):
            if i == 0 or curEnd <= intervals[i][0]:
                curEnd = intervals[i][1]
            else:
                return False

        return True
